#!/usr/bin/env bash
# Build the th06 (东方红魔乡) portable branch to WebAssembly via emscripten.
#
# Prereqcuisites:
#   - emsdk installed and activated:  source ~/emsdk/emsdk_env.sh
#   - src/autogenerated/Embeds.hpp present (generated by a prior native premake build,
#     or regenerate with: premake5 gmake)
#
# Output: dist/th06.{html,js,wasm} under the project directory.
set -euo pipefail

PROJ="${TH06_PORTABLE_DIR:-$HOME/projects/th06-portable}"
SRC="$PROJ/src"
OUT="$PROJ/dist"

if ! command -v emcc >/dev/null 2>&1; then
  echo "error: emcc not found. Run: source ~/emsdk/emsdk_env.sh" >&2
  exit 1
fi

if [ ! -f "$SRC/autogenerated/Embeds.hpp" ]; then
  echo "error: $SRC/autogenerated/Embeds.hpp missing. Run a native 'premake5 gmake' first." >&2
  exit 1
fi

mkdir -p "$OUT"

# DEBUG=1 enables assertions + readable stack traces to diagnose aborts.
if [ "${DEBUG:-0}" = "1" ]; then
  OPT_FLAGS=(-O0 -g -sASSERTIONS=2 -sSAFE_HEAP=0 -sSTACK_OVERFLOW_CHECK=2 -sGL_ASSERTIONS=1 -sGL_DEBUG=1)
else
  OPT_FLAGS=(-O2)
fi

# Source files mirror premake5.lua's file list. MIDI falls through to the
# MidiDefault (silent) backend since no win/linux/mac os.target matches under emscripten.
SOURCES=(
  "$SRC"/AnmManager.cpp
  "$SRC"/AsciiManager.cpp
  "$SRC"/BombData.cpp
  "$SRC"/BulletData.cpp
  "$SRC"/BulletManager.cpp
  "$SRC"/Chain.cpp
  "$SRC"/Controller.cpp
  "$SRC"/EclManager.cpp
  "$SRC"/EffectManager.cpp
  "$SRC"/Ending.cpp
  "$SRC"/EnemyEclInstr.cpp
  "$SRC"/EnemyManager.cpp
  "$SRC"/FileSystem.cpp
  "$SRC"/GameErrorContext.cpp
  "$SRC"/GameManager.cpp
  "$SRC"/GameWindow.cpp
  "$SRC"/Gui.cpp
  "$SRC"/ItemManager.cpp
  "$SRC"/main.cpp
  "$SRC"/MainMenu.cpp
  "$SRC"/MidiOutput.cpp
  "$SRC"/MusicRoom.cpp
  "$SRC"/Player.cpp
  "$SRC"/PointDevice.cpp
  "$SRC"/ReplayManager.cpp
  "$SRC"/ResultScreen.cpp
  "$SRC"/Rng.cpp
  "$SRC"/ScreenEffect.cpp
  "$SRC"/SoundPlayer.cpp
  "$SRC"/Stage.cpp
  "$SRC"/Supervisor.cpp
  "$SRC"/TextHelper.cpp
  "$SRC"/ZunMath.cpp
  "$SRC"/utils.cpp
  "$SRC"/ZunTimer.cpp
  "$SRC"/graphics/GLFunc.cpp
  "$SRC"/graphics/FixedFunctionGL.cpp
  "$SRC"/graphics/WebGL.cpp
  "$SRC"/graphics/Software.cpp
  "$SRC"/pbg3/FileAbstraction.cpp
  "$SRC"/pbg3/IPbg3Parser.cpp
  "$SRC"/pbg3/Pbg3Archive.cpp
  "$SRC"/pbg3/Pbg3Parser.cpp
  "$SRC"/midi/MidiDefault.cpp
  "$SRC"/thirdparty/sjis_converter.cpp
)

# Assets are NOT bundled into a single th06.data (that file would exceed the 20MB
# per-file limit). Instead copy each resource to dist/assets/ as an independent file
# and emit a manifest; play.html fetches them into MEMFS at startup (preRun).
if [ -d "${TH06_ASSETS_DIR:-}" ]; then
  echo "Staging assets from $TH06_ASSETS_DIR -> $OUT/assets/ (no bundling)"
  rm -rf "$OUT/assets"
  mkdir -p "$OUT/assets"
  # Copy preserving the bgm/ subdirectory structure the game expects.
  (cd "$TH06_ASSETS_DIR" && find . -type f -print0 | while IFS= read -r -d '' f; do
    rel="${f#./}"
    mkdir -p "$OUT/assets/$(dirname "$rel")"
    cp "$f" "$OUT/assets/$rel"
  done)
  # Manifest: newline-separated relative paths, consumed by play.html.
  (cd "$OUT/assets" && find . -type f -print | sed 's|^\./||' | sort) > "$OUT/assets/manifest.txt"
  echo "Staged $(wc -l < "$OUT/assets/manifest.txt" | tr -d ' ') asset files."
  echo "Largest asset: $(find "$OUT/assets" -type f -exec ls -l {} \; | sort -k5 -rn | head -1 | awk '{printf "%.1fMB", $5/1048576}')"
fi

set -x
emcc \
  -std=c++20 \
  -I"$SRC" \
  "${OPT_FLAGS[@]}" \
  -sUSE_SDL=2 \
  -sUSE_SDL_IMAGE=2 \
  -sSDL2_IMAGE_FORMATS='["png","jpg"]' \
  -sUSE_SDL_TTF=2 \
  -sFULL_ES2=1 \
  -sMIN_WEBGL_VERSION=1 \
  -sMAX_WEBGL_VERSION=2 \
  -sWASM=1 \
  -sALLOW_MEMORY_GROWTH=1 \
  -sEXIT_RUNTIME=0 \
  -sFORCE_FILESYSTEM=1 \
  -sEXPORTED_RUNTIME_METHODS='["FS","addRunDependency","removeRunDependency","callMain"]' \
  -Wno-unused-label \
  -Wno-c99-extensions \
  "${SOURCES[@]}" \
  -o "$OUT/th06.js"
set +x

echo ""
echo "Build OK -> $OUT/th06.{js,wasm}"
echo "Note: emitting th06.js (NOT th06.html). The emcc-generated th06.html carries no"
echo "      asset-injection logic, so opening it leaves MEMFS empty and the game aborts"
echo "      on the first missing file. The hand-written index.html / play.html do the"
echo "      manifest fetch into MEMFS, so always enter through those."

# play.html is the single source of truth for the page. Publish it as index.html
# (the platform's default entry) so the deployed entry always matches the source.
cp "$PROJ/web/play.html" "$OUT/index.html"
cp "$PROJ/web/play.html" "$OUT/play.html"
echo "Published page -> $OUT/index.html (and play.html), copied from web/play.html"

echo "Serve with:  cd '$OUT' && python3 -m http.server 8000"
echo "Then open:   http://localhost:8000/        (index.html)"
